step1-snapshot.ps1<pre><code># Process dashboard tutorial, step 1: show a table of the busiest processes in a native window.
#
# Teaches: Start-NativeHTMLKitScript, New-NativeHTMLKitWindow, Open-NativeHTMLKitHtml, building
#          HTML rows from objects with HtmlEncode, Set-NativeHTMLKitDocumentHtml, Wait-NativeHTMLKit.
# Run:     pwsh -File step1-snapshot.ps1      (Windows PowerShell 5.1: powershell.exe -File step1-snapshot.ps1)
# Guide:   docs/tutorials/process-dashboard.md (step 1 of 3)
$ErrorActionPreference = 'Stop'
Import-Module NativeHTMLKit -ErrorAction Stop
# The host runs this script again as its backend: everything below this line runs in that backend.
$app = Start-NativeHTMLKitScript -Name 'Process Dashboard'

$page = @'
&lt;!doctype html&gt;
&lt;html&gt;&lt;head&gt;&lt;meta charset="utf-8"&gt;&lt;style&gt;
  body { font: 14px sans-serif; margin: 0; background: #11161f; color: #e6ebf3; }
  main { padding: 18px 22px; }
  h1 { font-size: 20px; margin: 0 0 12px; }
  table { border-collapse: collapse; width: 100%; }
  th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #2a3445; }
  th { color: #9fb0c8; font-weight: 600; }
  td.num, th.num { text-align: right; }
&lt;/style&gt;&lt;/head&gt;
&lt;body&gt;&lt;main&gt;
  &lt;h1&gt;Top processes by memory&lt;/h1&gt;
  &lt;table&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Name&lt;/th&gt;&lt;th class="num"&gt;Id&lt;/th&gt;&lt;th class="num"&gt;Memory (MB)&lt;/th&gt;&lt;th class="num"&gt;CPU (s)&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody id="rows"&gt;&lt;/tbody&gt;
  &lt;/table&gt;
&lt;/main&gt;&lt;/body&gt;&lt;/html&gt;
'@

function ConvertTo-HtmlText([string]$Text) { return [System.Net.WebUtility]::HtmlEncode($Text) }

function Get-ProcessRowsHtml([int]$Top) {
    $rows = Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First $Top | ForEach-Object {
        '&lt;tr&gt;&lt;td&gt;{0}&lt;/td&gt;&lt;td class="num"&gt;{1}&lt;/td&gt;&lt;td class="num"&gt;{2:N1}&lt;/td&gt;&lt;td class="num"&gt;{3:N1}&lt;/td&gt;&lt;/tr&gt;' -f `
            (ConvertTo-HtmlText $_.ProcessName), $_.Id, ($_.WorkingSet64 / 1MB), [double]$_.CPU
    }
    return ($rows -join '')
}

try {
    $window = New-NativeHTMLKitWindow -Application $app -Title 'Process Dashboard' -Width 720 -Height 560
    $doc = Open-NativeHTMLKitHtml -Window $window -Html $page
    Set-NativeHTMLKitDocumentHtml -Document $doc -Element rows -Html (Get-ProcessRowsHtml -Top 15)
    Set-NativeHTMLKitReady -Application $app
    Wait-NativeHTMLKit -Application $app -UntilShutdown
} finally {
    Close-NativeHTMLKit -Application $app
}
</code></pre> <p>Run <code>pwsh -File step1-snapshot.ps1</code>.</p> <ul> <li>The page lives in a single-quoted here-string (<code>@' ... '@</code>), so PowerShell does not expand <code>$</code> or   backticks inside the HTML.</li> <li><code>Get-ProcessRowsHtml</code> builds <code>&lt;tr&gt;</code> rows with the <code>-f</code> format operator. Process names are not   under your control, so each one goes through <code>[System.Net.WebUtility]::HtmlEncode</code> before it   becomes markup.</li> <li><code>Set-NativeHTMLKitDocumentHtml -Element rows</code> replaces the children of <code>&lt;tbody id="rows"&gt;</code>.</li> <li><code>Set-NativeHTMLKitReady</code> comes after the first content is in place, so the window opens with a   filled table.</li> </ul>

step2-filter.ps1<pre><code># Process dashboard tutorial, step 2: filter and sort the table.
#
# Teaches: Register-NativeHTMLKitDocumentEvent for "input" and "submit" events, reading controls with
#          Get-NativeHTMLKitValue, keeping view state in one object that callbacks can change,
#          Set-NativeHTMLKitDocumentText for untrusted text.
# Run:     pwsh -File step2-filter.ps1        (Windows PowerShell 5.1: powershell.exe -File step2-filter.ps1)
# Guide:   docs/tutorials/process-dashboard.md (step 2 of 3)
$ErrorActionPreference = 'Stop'
Import-Module NativeHTMLKit -ErrorAction Stop
$app = Start-NativeHTMLKitScript -Name 'Process Dashboard'

$page = @'
&lt;!doctype html&gt;
&lt;html&gt;&lt;head&gt;&lt;meta charset="utf-8"&gt;&lt;style&gt;
  body { font: 14px sans-serif; margin: 0; background: #11161f; color: #e6ebf3; }
  main { padding: 18px 22px; }
  h1 { font-size: 20px; margin: 0 0 12px; }
  form { display: flex; gap: 8px; margin-bottom: 10px; }
  input, select { background: #1b2331; color: #e6ebf3; border: 1px solid #3a475c; border-radius: 5px; padding: 6px; }
  #filter { flex: 1; }
  button { background: #3574c6; color: white; border: 0; border-radius: 5px; padding: 6px 12px; }
  table { border-collapse: collapse; width: 100%; }
  th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #2a3445; }
  th { color: #9fb0c8; font-weight: 600; }
  td.num, th.num { text-align: right; }
  #summary { color: #9fb0c8; }
&lt;/style&gt;&lt;/head&gt;
&lt;body&gt;&lt;main&gt;
  &lt;h1&gt;Processes&lt;/h1&gt;
  &lt;form id="view-form"&gt;
    &lt;input id="filter" type="search" placeholder="Filter by name" aria-label="Filter by name"&gt;
    &lt;select id="sort" aria-label="Sort by"&gt;
      &lt;option value="memory"&gt;Memory&lt;/option&gt;&lt;option value="cpu"&gt;CPU time&lt;/option&gt;&lt;option value="name"&gt;Name&lt;/option&gt;
    &lt;/select&gt;
    &lt;button id="apply"&gt;Refresh&lt;/button&gt;
  &lt;/form&gt;
  &lt;p id="summary"&gt;&lt;/p&gt;
  &lt;table&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Name&lt;/th&gt;&lt;th class="num"&gt;Id&lt;/th&gt;&lt;th class="num"&gt;Memory (MB)&lt;/th&gt;&lt;th class="num"&gt;CPU (s)&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody id="rows"&gt;&lt;/tbody&gt;
  &lt;/table&gt;
&lt;/main&gt;&lt;/body&gt;&lt;/html&gt;
'@

function ConvertTo-HtmlText([string]$Text) { return [System.Net.WebUtility]::HtmlEncode($Text) }

function Update-View {
    $filter = (Get-NativeHTMLKitValue -Document $doc -Element filter).Trim()
    $sort = Get-NativeHTMLKitValue -Document $doc -Element sort
    $all = @(Get-Process)
    $shown = @($all | Where-Object { $filter -eq '' -or $_.ProcessName.IndexOf($filter, [StringComparison]::OrdinalIgnoreCase) -ge 0 })
    $sorted = switch ($sort) {
        'cpu'  { $shown | Sort-Object { [double]$_.CPU } -Descending }
        'name' { $shown | Sort-Object ProcessName }
        default { $shown | Sort-Object WorkingSet64 -Descending }
    }
    $html = @($sorted | Select-Object -First 25 | ForEach-Object {
        '&lt;tr&gt;&lt;td&gt;{0}&lt;/td&gt;&lt;td class="num"&gt;{1}&lt;/td&gt;&lt;td class="num"&gt;{2:N1}&lt;/td&gt;&lt;td class="num"&gt;{3:N1}&lt;/td&gt;&lt;/tr&gt;' -f `
            (ConvertTo-HtmlText $_.ProcessName), $_.Id, ($_.WorkingSet64 / 1MB), [double]$_.CPU
    }) -join ''
    Set-NativeHTMLKitDocumentHtml -Document $doc -Element rows -Html $html
    Set-NativeHTMLKitDocumentText -Document $doc -Element summary -Text ("Showing {0} of {1} processes" -f [Math]::Min(25, $shown.Count), $all.Count)
}

try {
    $window = New-NativeHTMLKitWindow -Application $app -Title 'Process Dashboard' -Width 720 -Height 600
    $doc = Open-NativeHTMLKitHtml -Window $window -Html $page
    # Callbacks run later, inside Wait-NativeHTMLKit, and can call the functions defined above.
    $null = Register-NativeHTMLKitDocumentEvent -Document $doc -Type input -Element filter -Callback { param($eventObject) Update-View }
    $null = Register-NativeHTMLKitDocumentEvent -Document $doc -Type change -Element sort -Callback { param($eventObject) Update-View }
    $null = Register-NativeHTMLKitDocumentEvent -Document $doc -Type submit -Element 'view-form' -Callback { param($eventObject) Update-View }
    Update-View
    Set-NativeHTMLKitReady -Application $app
    Wait-NativeHTMLKit -Application $app -UntilShutdown
} finally {
    Close-NativeHTMLKit -Application $app
}
</code></pre> <ul> <li>Three subscriptions call the same <code>Update-View</code> function: <code>input</code> on the search field (every   keystroke), <code>change</code> on the sort <code>&lt;select&gt;</code>, and <code>submit</code> on the form (Enter or the Refresh   button).</li> <li>Callbacks run later, inside <code>Wait-NativeHTMLKit</code>, and can call functions and read variables   (<code>$doc</code>) defined in the script.</li> <li>The filter uses <code>IndexOf(..., OrdinalIgnoreCase)</code> rather than <code>-like "*$filter*"</code>, so characters   like <code>[</code> typed by the user are not treated as wildcards.</li> <li><code>Set-NativeHTMLKitDocumentText</code> for the summary: text is never parsed as HTML.</li> </ul>

Method Returns Notes <code>form_data(form, *, submitter=None)</code> <code>{"entries": [...], "submitter": {"element", "node"} \| None}</code> Ordered entries <code>{"kind": "text", "name", "value"}</code> or <code>{"kind": "file", "name", "filename", "path"}</code>. Repeated names (checkbox groups, multiple selects) appear once per value; unchecked boxes are absent. With <code>submitter</code>, its <code>name</code>/<code>value</code> is included. <code>request_submit(form, *, submitter=None)</code> <code>{"submitted": bool, "default_prevented": bool}</code> Submit as if the user clicked the submitter: runs constraint validation; if valid fires <code>submit</code>, else fires <code>invalid</code> on each failing control and <code>submitted</code> is <code>False</code>. <code>reset_form(form)</code> <code>{"reset": bool, "default_prevented": bool}</code> Restore default values; fires <code>reset</code>. <code>validity(element)</code> <code>{"valid", "will_validate", "message", "flags": {...}}</code> <code>flags</code>: <code>valueMissing</code>, <code>typeMismatch</code>, <code>patternMismatch</code>, <code>tooLong</code>, <code>tooShort</code>, <code>rangeUnderflow</code>, <code>rangeOverflow</code>, <code>stepMismatch</code>, <code>badInput</code>, <code>customError</code>. <code>message</code> is the host's validation message. <code>check_validity(element)</code> <code>{"valid", "count", "invalid": [ids]}</code> For a control or a whole form. <code>set_custom_validity(element, message="")</code> <code>{"valid", "message", "flags"}</code> A non-empty message makes the control invalid (<code>customError</code>) until cleared with <code>""</code>. <code>options(element)</code> <code>[{"value", "label", "selected", "disabled"}, ...]</code> Options of a <code>&lt;select&gt;</code>. <code>set_selected_values(element, values)</code> <code>None</code> Select exactly these option values. <code>files(element)</code> <code>[str]</code> Paths chosen in an <code>&lt;input type="file"&gt;</code> (the host shows the native picker on click). <p><code>form</code> and <code>submitter</code> accept an id or a <code>Node</code>; <code>validity</code>, <code>check_validity</code>, <code>options</code>, <code>set_selected_values</code> and <code>files</code> take an id.</p> <pre><code>result = document.request_submit("signup", submitter="create")
if result["submitted"]:
    values = {e["name"]: e["value"] for e in document.form_data("signup")["entries"] if e["kind"] == "text"}
</code></pre>

step1_snapshot.py<pre><code>"""Process dashboard tutorial, step 1: show a table of the busiest processes in a native window.

What it teaches
  * ``Application.start`` -&gt; ``open_html`` -&gt; ``replace_html`` -&gt; ``app.run()``
  * building HTML rows from data with ``html.escape``
  * filling the page before ``app.run()`` announces readiness, so the window opens complete

Run:    uv run process_dashboard/step1_snapshot.py
Guide:  docs/tutorials/process-dashboard.md (step 1 of 3)
"""
from __future__ import annotations

import html

from nativehtmlkit import Application
from processes import list_processes

PAGE = """&lt;!doctype html&gt;
&lt;html&gt;&lt;head&gt;&lt;meta charset="utf-8"&gt;&lt;style&gt;
  body { font: 14px sans-serif; margin: 0; background: #11161f; color: #e6ebf3; }
  main { padding: 18px 22px; }
  h1 { font-size: 20px; margin: 0 0 12px; }
  table { border-collapse: collapse; width: 100%; }
  th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #2a3445; }
  th { color: #9fb0c8; font-weight: 600; }
  td.num, th.num { text-align: right; }
&lt;/style&gt;&lt;/head&gt;
&lt;body&gt;&lt;main&gt;
  &lt;h1&gt;Top processes by memory&lt;/h1&gt;
  &lt;table&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Name&lt;/th&gt;&lt;th class="num"&gt;Id&lt;/th&gt;&lt;th class="num"&gt;Memory (MB)&lt;/th&gt;&lt;th class="num"&gt;CPU (s)&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody id="rows"&gt;&lt;/tbody&gt;
  &lt;/table&gt;
&lt;/main&gt;&lt;/body&gt;&lt;/html&gt;"""


def rows_html(processes) -&gt; str:
    # Process names are not under your control: escape them before they become markup.
    return "".join(f'&lt;tr&gt;&lt;td&gt;{html.escape(p.name)}&lt;/td&gt;&lt;td class="num"&gt;{p.pid}&lt;/td&gt;'
                   f'&lt;td class="num"&gt;{p.memory_mb:,.1f}&lt;/td&gt;&lt;td class="num"&gt;{p.cpu_seconds:,.1f}&lt;/td&gt;&lt;/tr&gt;'
                   for p in processes)


def build(app: Application):
    window = app.open_html(PAGE, title="Process Dashboard", width=720, height=560)
    top = sorted(list_processes(), key=lambda p: p.memory_mb, reverse=True)[:15]
    window.document.replace_html("rows", rows_html(top))
    return window.document


def main() -&gt; None:
    # The host runs this script again as its backend: keep side effects inside main().
    with Application.start(name="Process Dashboard") as app:
        build(app)
        app.run()


if __name__ == "__main__":
    main()
</code></pre> <p>Run <code>uv run step1_snapshot.py</code>.</p> <ul> <li>The page is a Python string. Every element the code changes has an <code>id</code>: here only the table   body <code>rows</code>.</li> <li><code>rows_html</code> builds <code>&lt;tr&gt;</code> rows with f-strings. Process names are not under your control, so each   one goes through <code>html.escape</code> before it becomes markup.</li> <li><code>replace_html("rows", ...)</code> replaces the children of <code>&lt;tbody id="rows"&gt;</code>.</li> <li><code>build()</code> fills the table before <code>app.run()</code> announces that the app is ready, so the window   opens with a full table. <code>build()</code> is also what the tests call.</li> <li><code>from processes import list_processes</code> works because the script's folder is on <code>sys.path</code>, in   the backend run as well.</li> </ul>

step2_filter.py<pre><code>"""Process dashboard tutorial, step 2: filter and sort the table.

What it teaches
  * ``input``, ``change`` and ``submit`` events that all call one ``update_view`` function
  * reading controls with ``get_value``
  * ``set_text`` for text that must never be parsed as HTML

Run:    uv run process_dashboard/step2_filter.py
Guide:  docs/tutorials/process-dashboard.md (step 2 of 3)
"""
from __future__ import annotations

import html

from nativehtmlkit import Application, Document
from processes import list_processes

PAGE = """&lt;!doctype html&gt;
&lt;html&gt;&lt;head&gt;&lt;meta charset="utf-8"&gt;&lt;style&gt;
  body { font: 14px sans-serif; margin: 0; background: #11161f; color: #e6ebf3; }
  main { padding: 18px 22px; }
  h1 { font-size: 20px; margin: 0 0 12px; }
  form { display: flex; gap: 8px; margin-bottom: 10px; }
  input, select { background: #1b2331; color: #e6ebf3; border: 1px solid #3a475c; border-radius: 5px; padding: 6px; }
  #filter { flex: 1; }
  button { background: #3574c6; color: white; border: 0; border-radius: 5px; padding: 6px 12px; }
  table { border-collapse: collapse; width: 100%; }
  th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #2a3445; }
  th { color: #9fb0c8; font-weight: 600; }
  td.num, th.num { text-align: right; }
  #summary { color: #9fb0c8; }
&lt;/style&gt;&lt;/head&gt;
&lt;body&gt;&lt;main&gt;
  &lt;h1&gt;Processes&lt;/h1&gt;
  &lt;form id="view-form"&gt;
    &lt;input id="filter" type="search" placeholder="Filter by name" aria-label="Filter by name"&gt;
    &lt;select id="sort" aria-label="Sort by"&gt;
      &lt;option value="memory"&gt;Memory&lt;/option&gt;&lt;option value="cpu"&gt;CPU time&lt;/option&gt;&lt;option value="name"&gt;Name&lt;/option&gt;
    &lt;/select&gt;
    &lt;button id="apply"&gt;Refresh&lt;/button&gt;
  &lt;/form&gt;
  &lt;p id="summary"&gt;&lt;/p&gt;
  &lt;table&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Name&lt;/th&gt;&lt;th class="num"&gt;Id&lt;/th&gt;&lt;th class="num"&gt;Memory (MB)&lt;/th&gt;&lt;th class="num"&gt;CPU (s)&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody id="rows"&gt;&lt;/tbody&gt;
  &lt;/table&gt;
&lt;/main&gt;&lt;/body&gt;&lt;/html&gt;"""

SORT_KEYS = {
    "memory": (lambda p: p.memory_mb, True),
    "cpu": (lambda p: p.cpu_seconds, True),
    "name": (lambda p: p.name.lower(), False),
}
SHOWN = 25


def update_view(document: Document) -&gt; None:
    needle = document.get_value("filter").strip().lower()
    key, descending = SORT_KEYS.get(document.get_value("sort"), SORT_KEYS["memory"])
    everything = list_processes()
    shown = [p for p in everything if needle in p.name.lower()]
    top = sorted(shown, key=key, reverse=descending)[:SHOWN]
    document.replace_html("rows", "".join(
        f'&lt;tr&gt;&lt;td&gt;{html.escape(p.name)}&lt;/td&gt;&lt;td class="num"&gt;{p.pid}&lt;/td&gt;'
        f'&lt;td class="num"&gt;{p.memory_mb:,.1f}&lt;/td&gt;&lt;td class="num"&gt;{p.cpu_seconds:,.1f}&lt;/td&gt;&lt;/tr&gt;' for p in top))
    document.set_text("summary", f"Showing {len(top)} of {len(everything)} processes")


def build(app: Application) -&gt; Document:
    window = app.open_html(PAGE, title="Process Dashboard", width=720, height=600)
    document = window.document
    # Callbacks run later, on the SDK's event thread, and may call any SDK method.
    document.on("input", lambda _event: update_view(document), element="filter")
    document.on("change", lambda _event: update_view(document), element="sort")
    document.on("submit", lambda _event: update_view(document), element="view-form")
    update_view(document)
    return document


def main() -&gt; None:
    with Application.start(name="Process Dashboard") as app:
        build(app)
        app.run()


if __name__ == "__main__":
    main()
</code></pre> <ul> <li>Three subscriptions call the same <code>update_view</code> function: <code>input</code> on the search field (every   keystroke), <code>change</code> on the sort <code>&lt;select&gt;</code>, and <code>submit</code> on the form (Enter or the Refresh   button, which submits the form because it is a <code>&lt;button&gt;</code> inside it).</li> <li><code>get_value</code> reads the current filter text and the selected sort option.</li> <li><code>set_text</code> writes the summary: text is never parsed as HTML.</li> <li><code>SORT_KEYS</code> maps each <code>&lt;option value&gt;</code> to a sort key and direction, so an unexpected value falls   back to memory order instead of failing.</li> </ul>
